problems.solutionCode:
export function readCarrierReference(payload: unknown): string | undefined {
  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) return undefined;
  if (!('trackingId' in payload)) return undefined;
  return typeof payload.trackingId === 'string' ? payload.trackingId : undefined;
}

problems.trapMutant:
