  if (typeof payload === 'object' && Object.prototype.hasOwnProperty.call(payload, 'trackingId')) {
    return typeof (payload as { trackingId?: unknown }).trackingId === 'string' ? (payload as { trackingId?: unknown }).trackingId as string : undefined;
  }
  return undefined;
}

