export function isGatewayNotice(value: unknown): value is GatewayNotice {
  return typeof value === 'object' && value !== null && 'route' in value;
}

problems.solutionCode:
type GatewayNotice = { route: string; retryAfterSeconds: number };

function isGatewayRecord(value: object): value is GatewayNotice {
  if (!('route' in value) || !('retryAfterSeconds' in value)) return false;
  if (!Object.prototype.hasOwnProperty.call(value, 'route')) return false;
  if (!Object.prototype.hasOwnProperty.call(value, 'retryAfterSeconds')) return false;
  return typeof value.route === 'string'
    && typeof value.retryAfterSeconds === 'number'
    && Number.isFinite(value.retryAfterSeconds);
}

export function isGatewayNotice(value: unknown): value is GatewayNotice {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false;
  return isGatewayRecord(value);
}

